import json

def transform(grid):
    n = len(grid)
    result = [row[:] for row in grid]

    # Find diagonal positions with 1s
    diag_positions = [i for i in range(n) if grid[i][i] == 1]

    if not diag_positions:
        return result

    last_diag = max(diag_positions)

    # Pattern: alternate between diagonal (col, col) and (col-1, col)
    # For columns after last_diag, fill 4 positions

    # Determine the offset columns
    columns = [last_diag + 1 + i*2 for i in range(4)]

    # Fill pattern: 0 -> diag, 1 -> below diag, 0 -> diag, 1 -> below diag
    for i, col in enumerate(columns):
        if i % 2 == 0:
            # On diagonal
            result[col][col] = 2
        else:
            # One row above
            result[col-1][col] = 2

    return result

